(()=>{
 const $=id=>document.getElementById(id), D=window.Dirks, fmt=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
 let task=D.create(), timer, saved=[];const key='sentinel-light-sim-receipts-v1';
 try{const data=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(data))saved=data.filter(r=>r&&typeof r.id==='string'&&Array.isArray(r.events)).slice(0,25);}catch{}
 function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,5000);}
 function run(fn){try{fn();render();}catch(e){toast(e.message);}}
 function text(tag,value,className){const el=document.createElement(tag);el.textContent=value;if(className)el.className=className;return el;}
 function receipt(){if(!['confirmed','unresolved','failed','cancelled'].includes(task.state))return;const r={id:task.id,state:task.state,total:D.total(task),budget:task.budget,approval:task.approval,events:task.events,payment:task.payment?JSON.parse(JSON.stringify(task.payment)):null,at:new Date().toISOString(),simulation:true};saved=[r,...saved.filter(x=>x.id!==r.id)].slice(0,25);try{localStorage.setItem(key,JSON.stringify(saved));}catch{toast('Receipt is available this session; browser storage is unavailable.');}}
 function render(){
  const active=task.state!=='draft';$('task-area').hidden=!active;if(!active)return;
  const editable=['review','approved'].includes(task.state), labels={review:'Needs your review',approved:'Approved · simulation',confirmed:'Order confirmed · simulated',unresolved:'Outcome unresolved',failed:'Order rejected · simulated',cancelled:'Stopped before submission'};
  $('task-state').textContent=labels[task.state];$('task-summary').textContent='“'+task.request+'”';$('items').replaceChildren();
  for(const item of task.items){const row=text('div','','item');row.append(text('span',item.icon,'item-icon'));const copy=text('div','','item-copy');copy.append(text('strong',item.name),text('small',item.detail));row.append(copy);const qty=text('div','','qty');
   for(const [label,delta] of [['−',-1],['+',1]]){const b=text('button',label);b.type='button';b.setAttribute('aria-label',(delta<0?'Remove one ':'Add one ')+item.name);b.disabled=!editable||item.qty+delta<0||item.qty+delta>9;b.addEventListener('click',()=>run(()=>D.edit(task,item.id,delta)));if(delta>0)qty.append(text('span',String(item.qty)));qty.append(b);}row.append(qty,text('span',fmt(item.price*item.qty),'item-price'));$('items').append(row);
  }
  const total=D.total(task),remaining=Math.round((task.budget-total)*100)/100;$('subtotal').textContent=fmt(total-13);$('total').textContent=fmt(total);$('budget-status').textContent=remaining>=0?fmt(remaining)+' within your '+fmt(task.budget)+' budget':fmt(-remaining)+' over your '+fmt(task.budget)+' budget';$('budget-status').className='budget-status'+(remaining<0?' over':'');
  $('approve').hidden=task.state!=='review';$('approve').disabled=remaining<0||!task.items.some(i=>i.qty>0);$('approve').textContent='Approve '+fmt(total)+' basket';$('dispatch-controls').hidden=task.state!=='approved';$('cancel').hidden=!editable;$('new-task').hidden=editable;$('reconcile').hidden=task.state!=='unresolved';$('payment-check').hidden=!task.dispatched||!['pending','unresolved'].includes(task.payment?.status);$('approval-note').textContent=task.state==='approved'?'This exact basket is approved. Changing an item will require a new approval.':task.state==='review'?'Review the basket, demo recipient and NunnPay total before approving.':'This task is recorded in Activity & receipts.';
  $('outcome').hidden=editable;$('outcome').replaceChildren();const results={confirmed:['Order confirmed in simulation.','The mock provider accepted the demo order. Payment status is tracked separately. No real order was placed.'],unresolved:['We’re checking, not guessing.','The simulated provider timed out. No automatic retry. Check the original order status before submitting anything again.'],failed:['The order did not go through.','The simulated provider rejected the request. No order was created.'],cancelled:['Stopped. You’re in control.','This task was cancelled before dispatch. Nothing was submitted.']};if(results[task.state])$('outcome').append(text('strong',results[task.state][0]),text('div',results[task.state][1]));if(task.dispatched&&task.payment){$('outcome').append(text('div','NunnPay: '+task.payment.status+' · simulated · '+fmt(task.payment.amountMinor/100)+'. No funds moved.'));if(task.payment.status==='confirmed'&&task.state!=='confirmed')$('outcome').append(text('div','Payment and order differ: reconciliation or refund review would be required. Do not pay again.'));}
  $('events').replaceChildren();for(const e of task.events){const li=document.createElement('li');const time=text('time',new Date(e.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}));time.dateTime=e.at;li.append(time,document.createTextNode(e.label));$('events').append(li);}receipt();
  $('task-form').querySelector('button[type="submit"]').disabled=true;$('request').disabled=true;$('budget').disabled=true;
 }
 function newTask(){task=D.create();$('task-area').hidden=true;$('task-form').querySelector('button[type="submit"]').disabled=false;$('request').disabled=false;$('budget').disabled=false;$('request').focus();toast('Ready for a new grocery task.');}
 $('task-form').addEventListener('submit',e=>{e.preventDefault();run(()=>{D.prepare(task,$('request').value,Number($('budget').value));setTimeout(()=>$('task-area').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'}),0);});});
 $('approve').addEventListener('click',()=>run(()=>D.approve(task)));$('dispatch').addEventListener('click',()=>run(()=>D.dispatch(task,$('scenario').value,$('payment-scenario').value)));$('cancel').addEventListener('click',()=>run(()=>D.cancel(task)));$('reconcile').addEventListener('click',()=>run(()=>D.reconcile(task)));$('new-task').addEventListener('click',newTask);$('payment-check').addEventListener('click',()=>run(()=>D.reconcilePayment(task)));
 $('voice-demo').addEventListener('click',()=>{if(task.state!=='draft'){toast('Start a new task to try another request.');return;}$('request').value='Get my weekly groceries under $85. Ask me before making substitutions.';$('budget').value=85;toast('Voice example inserted. Microphone input is not connected in this prototype.');$('request').focus();});
 $('grocery-shortcut').addEventListener('click',()=>{if(task.state==='draft'){$('request').value='Get my weekly groceries under $85. Ask me before making substitutions.';$('request').focus();}else $('task-area').scrollIntoView({behavior:'smooth'});});
 document.querySelectorAll('[data-future]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.future+' is planned for a later capability release.')));
 function showReceipts(){const list=$('receipts-list');list.replaceChildren();if(!saved.length){list.append(text('div','Your first receipt will appear after a simulated task reaches an outcome.','empty'));return;}for(const r of saved){const card=text('article','','receipt');const top=text('div','','receipt-top');top.append(text('h2','Grocery DIRK · '+r.id),text('span',r.state+' · simulated','state'));card.append(top);const dl=document.createElement('dl');for(const [k,v] of [['Recorded',new Date(r.at).toLocaleString()],['Basket total',fmt(r.total)],['Budget',fmt(r.budget)],['Approval',r.approval?'Revision '+r.approval.revision+' · '+fmt(r.approval.total):'No approval retained'],['NunnPay',r.payment?r.payment.status+' · simulated · '+fmt(r.payment.amountMinor/100):'Not recorded in this earlier receipt'],['Payment reference',r.payment?.providerReference||'No confirmation evidence'],['Provider',r.state==='confirmed'?'Mock order confirmation · payment tracked separately':r.state==='unresolved'?'Unknown · status check required':'No confirmed order'],['Evidence','Local simulator only · not a live Sentinel receipt']])dl.append(text('dt',k),text('dd',v));card.append(dl);list.append(card);}}
 document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==b.dataset.view+'-view');$('breadcrumb').textContent=b.dataset.view==='home'?'My space / A little less to do':b.textContent.trim();if(b.dataset.view==='receipts')showReceipts();window.scrollTo(0,0);}));
 $('clear-history').addEventListener('click',()=>{saved=[];try{localStorage.removeItem(key);}catch{}showReceipts();toast('Local receipt history cleared.');});
 $('about-button').addEventListener('click',()=>$('about').showModal());$('close-about').addEventListener('click',()=>$('about').close());$('about').addEventListener('click',e=>{if(e.target===$('about'))$('about').close();});
})();
